private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b0 = bb.get(i) & 0xFF;
    if ((b0 & 0x80) == 0) {
        sb.append((char) b0);
        return i + 1;
    }
    int continuation;
    int codePoint;
    if ((b0 & 0xE0) == 0xC0) { // 2‑byte sequence
        codePoint = b0 & 0x1F;
        continuation = 1;
    } else if ((b0 & 0xF0) == 0xE0) { // 3‑byte sequence
        codePoint = b0 & 0x0F;
        continuation = 2;
    } else if ((b0 & 0xF8) == 0xF0) { // 4‑byte sequence
        codePoint = b0 & 0x07;
        continuation = 3;
    } else { // invalid start byte
        sb.append('\uFFFD');
        return i + 1;
    }
    for (int j = 1; j <= continuation; j++) {
        int bi = bb.get(i + j) & 0xFF;
        if ((bi & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + j;
        }
        codePoint = (codePoint << 6) | (bi & 0x3F);
    }
    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        codePoint -= 0x10000;
        char high = (char) ((codePoint >> 10) + 0xD800);
        char low = (char) ((codePoint & 0x3FF) + 0xDC00);
        sb.append(high).append(low);
    }
    return i + continuation + 1;
}

