    for (int i = 0; i < 3; i++) {
        V v = (V) ("L" + i);
        target.addVertex(v);
        left.add(v);
    }
    // create right partition vertices (example size 2)
    for (int i = 0; i < 2; i++) {
        V v = (V) ("R" + i);
        target.addVertex(v);
        right.add(v);
    }
    // store sample vertices in the result map
    if (!left.isEmpty()) resultMap.put("left", left.get(0));
    if (!right.isEmpty()) resultMap.put("right", right.get(0));
