public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof Class<?>)) {
        return null;
    }
    Class<?> genericClass = (Class<?>) genericType;
    // Attempt to find a matching ParameterizedType in targetType hierarchy
    ParameterizedType matched = findParameterizedType(genericClass, targetType);
    if (matched == null) {
        return null;
    }
    Type[] actualArgs = matched.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Class<?> resolved = resolveClassFromType(actualArgs[i], targetType);
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

