public Mappings diffStructure(String tableName, Mappings mappings) {
    // Obtain the current index mapping
    Mappings current = getMappingsFromIndex(tableName);
    if (current == null) {
        return new Mappings();
    }

    // Prepare a new mapping to hold the differences
    Mappings diff = new Mappings();

    // Assume each mapping has a method getProperties() returning a map of field names to field definitions
    Map<String, Object> currentProps = current.getProperties();
    if (currentProps == null) {
        return diff;
    }

    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String fieldName = entry.getKey();
        // Skip the _source field to avoid conflicts
        if ("_source".equals(fieldName)) {
            continue;
        }
        // If the input mappings do not contain this field, add it to the diff
        if (!mappings.containsField(fieldName)) {
            diff.addProperty(fieldName, entry.getValue());
        }
    }

    return diff;
}

