private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == null && suffix == null;
    }
    int suffixLen = suffix.length();
    int strLen = str.length();
    if (suffixLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String path = decode ? u.getPath() : u.getRawPath();
    if (path == null) {
        return result;
    }
    // Ignore leading '/' for absolute paths
    int start = 0;
    while (start < path.length() && path.charAt(start) == '/') {
        start++;
    }
    String trimmed = path.substring(start);
    if (trimmed.isEmpty()) {
        return result;
    }
    String[] segments = trimmed.split("/");
    for (String seg : segments) {
        if (seg.isEmpty()) {
            continue;
        }
        result.add(new PathSegmentImpl(seg));
    }
    return result;
}

