    // add the edge to the source vertex's list
    index.get(sourceVertex).add(e);
    // also add the edge to the target vertex's list for convenience
    if (!index.containsKey(targetVertex)) {
        index.put(targetVertex, new ArrayList<>());
    }
    index.get(targetVertex).add(e);
}

