@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Target type must be Character or primitive char
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return s.charAt(0);
            }
        }
        if (value instanceof Number) {
            int num = ((Number) value).intValue();
            if (num >= Character.MIN_VALUE && num <= Character.MAX_VALUE) {
                return (char) num;
            }
        }
        // Fallback: use toString and take first character if possible
        String str = value.toString();
        if (str != null && str.length() == 1) {
            return str.charAt(0);
        }
    }
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to " + type.getName());
}

