public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // c == '\\'
        if (i + 1 >= length) {
            // trailing backslash, treat literally
            sb.append('\\');
            continue;
        }
        char next = str.charAt(i + 1);
        if (next == '\\') {
            // escaped backslash
            sb.append('\\');
            i++; // skip the next backslash
            continue;
        }
        switch (next) {
            case 'b':
                sb.append('\b');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\'':
                sb.append('\'');
                break;
            case 'u':
                if (i + 6 <= length) {
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int value = Integer.parseInt(hex, 16);
                        sb.append((char) value);
                        i += 5; // skip 'u' and four hex digits
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence: \\u" + hex);
                    }
                } else {
                    throw new IllegalArgumentException("Incomplete Unicode escape sequence at position " + i);
                }
                break;
            default:
                // Any other escaped character is taken literally
                sb.append(next);
                break;
        }
        i++; // skip the escaped character
    }
    return sb.toString();
}

