int removeUnusedNodes() {
    int count = 0;
    if (root == null) {
        return 0;
    }
    if (!root.isActive()) {
        root = null;
        return 1;
    }
    java.util.Deque<java.util.List<Category>> stack = new java.util.ArrayDeque<>();
    stack.push(root.getChildren());
    while (!stack.isEmpty()) {
        java.util.Iterator<Category> it = stack.pop().iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove();
                count++;
            } else {
                stack.push(child.getChildren());
            }
        }
    }
    return count;
}

