private void check(String modelName) throws IllegalStateException {
    try {
        Class<?> clazz = Class.forName(modelName);
        java.util.List<Integer> indices = new java.util.ArrayList<>();
        for (java.lang.reflect.Field field : clazz.getDeclaredFields()) {
            ShardingKey key = field.getAnnotation(ShardingKey.class);
            if (key != null) {
                indices.add(key.index());
            }
        }
        if (!indices.isEmpty()) {
            java.util.Collections.sort(indices);
            for (int i = 0; i < indices.size(); i++) {
                if (indices.get(i) != i) {
                    throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
                }
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Model not found: " + modelName, e);
    }
}

