        nameIdx = addUtf8(name);
    }
    descrIdx = findUtf8(descriptor);
    if(descrIdx == NOT_FOUND){
        descrIdx = addUtf8(descriptor);
    }
    // Search for an existing NameAndType entry with the same name and descriptor indices
    for(int loc = 1; loc < maxPoolSize; loc++){
        if(types[loc] == NAME_AND_TYPE){
            if(readNameAndTypeNameIndex(loc) == nameIdx && 
               readNameAndTypeDescriptorIndex(loc) == descrIdx){
                return loc; // already exists
            }
        }
    }
    // Add a new NameAndType entry to the constant pool
    int newIndex = ++maxPoolSize;
    types[newIndex] = NAME_AND_TYPE;
    // Ensure the byteCode array has enough space: tag (1 byte) + two u2 indices = 5 bytes
    int currentLen = byteCode.length;
    byteCode = java.util.Arrays.copyOf(byteCode, currentLen + 5);
    byteCode[currentLen] = NAME_AND_TYPE; // tag
    writeU2(byteCode, currentLen + 1, nameIdx); // name_index
    writeU2(byteCode, currentLen + 3, descrIdx); // descriptor_index
    offsets[newIndex] = currentLen; // record the start offset of this entry
    return newIndex;
}

